constraints:
1 ≤ N ≤ 10^{7}

expected time complexity: O(Log(N))
expected auxiliary space: O(Log(N))

standard_solution_code:
class Solution:

	def ExcelColumn(self, N):
		temp = N
		st = ''
		while temp:
			lt = temp % 26
			if lt == 0:
				st = 'Z' + st
				temp = temp // 26 - 1
			else:
				st = chr(64 + lt) + st
				temp = temp // 26
		return st
